import { useId, type HTMLAttributes, type KeyboardEvent, type Ref } from 'react';
import {
    moveRovingFocus,
    rovingIndex,
    SEGMENTED_ITEM,
    SEGMENTED_ITEM_IDLE,
    SEGMENTED_ITEM_SELECTED,
    SEGMENTED_LIST,
    type ChoiceItem,
} from './choice';
import { cx, INTERACTIVE } from './cx';
import { Icon } from './Icon';

export type TabsVariant = 'underline' | 'segmented';

export interface TabItem<V extends string = string> extends ChoiceItem<V> {
    /** Tab element id (generated by default). Pass it to give the panel `aria-labelledby`. */
    id?: string;
    /** Id of the role="tabpanel" element this tab controls (aria-controls). */
    panelId?: string;
}

export interface TabsProps<V extends string = string> extends Omit<
    HTMLAttributes<HTMLDivElement>,
    'onChange' | 'role' | 'defaultValue' | 'children'
> {
    items: readonly TabItem<V>[];
    /** Controlled selected value. */
    value: V;
    onChange: (value: V) => void;
    variant?: TabsVariant;
    /** Segmented variant only: stretch to the container width with equal items. */
    fullWidth?: boolean;
    ref?: Ref<HTMLDivElement>;
}

const UNDERLINE_LIST = 'no-drag-region pointer-events-auto flex items-end gap-1 border-b border-stroke';

const UNDERLINE_TAB =
    'relative inline-flex h-[var(--kb-control-h)] items-center gap-2 rounded-t-sm px-3 text-[0.8125rem] leading-5 whitespace-nowrap transition-colors duration-[var(--kb-dur-fast)] after:absolute after:inset-x-3 after:bottom-0 after:h-0.75 after:rounded-full disabled:cursor-not-allowed disabled:text-fg-3';

/**
 * Tab strip (role="tablist"/"tab"). Controlled; roving tabindex with Arrow Left/Right (mirrored in RTL),
 * Home and End; selection follows focus (automatic activation), disabled tabs are skipped. Use `aria-label` or
 * `aria-labelledby` on the list. For a value picker without panels use `Segmented` (radiogroup).
 */
export function Tabs<V extends string = string>({
    items,
    value,
    onChange,
    variant = 'underline',
    fullWidth = false,
    className,
    onKeyDown,
    ...rest
}: TabsProps<V>) {
    const baseId = useId();
    const focusIndex = rovingIndex(items, value);
    const segmented = variant === 'segmented';

    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        onKeyDown?.(event);
        if (event.defaultPrevented) return;
        const index = moveRovingFocus(event, items, false);
        if (index !== null && items[index].value !== value) onChange(items[index].value);
    };

    return (
        <div
            {...rest}
            role="tablist"
            aria-orientation="horizontal"
            onKeyDown={handleKeyDown}
            className={cx(segmented ? cx(SEGMENTED_LIST, fullWidth ? 'flex w-full' : 'inline-flex') : UNDERLINE_LIST, className)}
        >
            {items.map((item, index) => {
                const selected = item.value === value;
                return (
                    <button
                        key={item.value}
                        data-kb-choice=""
                        type="button"
                        role="tab"
                        id={item.id ?? `${baseId}-tab-${index}`}
                        aria-selected={selected}
                        aria-controls={item.panelId}
                        tabIndex={index === focusIndex ? 0 : -1}
                        disabled={item.disabled}
                        onClick={() => {
                            if (!selected) onChange(item.value);
                        }}
                        className={cx(
                            INTERACTIVE,
                            segmented
                                ? cx(SEGMENTED_ITEM, selected ? SEGMENTED_ITEM_SELECTED : SEGMENTED_ITEM_IDLE, fullWidth && 'flex-1')
                                : cx(
                                      UNDERLINE_TAB,
                                      selected
                                          ? 'text-fg-1 after:bg-[var(--kb-accent)]'
                                          : 'text-fg-2 after:bg-transparent enabled:hover:bg-[var(--kb-fill-hover)] enabled:hover:text-fg-1'
                                  )
                        )}
                    >
                        {item.icon && <Icon name={item.icon} size={16} filled={selected} />}
                        <span>{item.label}</span>
                    </button>
                );
            })}
        </div>
    );
}
